T='takhtajanfaddeev1974nonlinear'; K='korepinfaddeev1975quantization'; F='faddeevkorepin1978quantum'; C='chenliulu2020sinegordon'; Z='zamolodchikov1977exact'; J='zamolodchikov1977jetp'; Q='sklyaninfaddeev1978quantum'; Y='yafaev2004lectures'; R='froehlich1975quantized'; P='pohlmeyer1976integrable'; V='zakharovmikhailov1978relativistic'; O='zamolodchikovzamolodchikov1978on'; CO='coleman1975equivalence'
